ApiSetFormValue.printed:
mutation ApiSetFormValue($organizationHostedJobsPageName: String!, $formRenderIdentifier: String!, $path: String!, $value: JSON, $formDefinitionIdentifier: String) {
  setFormValue(
    organizationHostedJobsPageName: $organizationHostedJobsPageName
    formRenderIdentifier: $formRenderIdentifier
    path: $path
    value: $value
    formDefinitionIdentifier: $formDefinitionIdentifier
  ) {
    ...FormRenderParts
  }
}

fragment JSONBoxParts on JSONBox {
  value
}

fragment FileParts on File {
  id
  filename
}

fragment FormFieldEntryParts on FormFieldEntry {
  id
  field
  fieldValue {
    ... on JSONBox {
      ...JSONBoxParts
    }
    ... on File {
      ...FileParts
    }
    ... on FileList {
      files {
        ...FileParts
      }
    }
  }
  isRequired
  descriptionHtml
  isHidden
}

fragment FormRenderParts on FormRender {
  id
  formControls {
    identifier
    title
  }
  errorMessages
  formErrors {
    message
    fieldEntryId
  }
  sections {
    title
    descriptionHtml
    fieldEntries {
      ...FormFieldEntryParts
    }
    isHidden
  }
  sourceFormDefinitionId
}

